import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

/**
 * @typedef {object} NodeConfig
 * @property {string|Array<any>} [imageUrl]
 * @property {Array<number>} [position]
 * @property {Array<number>} [rotation]
 * @property {Array<number>} [scale]
 * @property {any} [textContent]
 * @property {any} [intent]
 * @property {any} [visual]
 * @property {Array<any>} [cinematicPrimitives]
 */

/**
 * @typedef {object} NodeContext
 * @property {any} THREE
 * @property {object} textureLoader
 * @property {object} glbLoader
 * @property {object} fontAtlas
 * @property {object} primitives
 * @property {function} emit
 * @property {string} [tier]
 */

/**
 * Create a hero headline node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Euler } = ctx.THREE;

  // Root container
  const root = new Group();

  // -----------------------------------------------------------------
  // 1️⃣  Plane geometry with image texture
  // -----------------------------------------------------------------
  // Default plane size – width: 6, height: 4 (adjustable if needed)
  const planeGeom = new PlaneGeometry(6, 4);
  const planeMat = new MeshBasicNodeMaterial();
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  /** @type {import('three').Texture|null} */
  let loadedTex = null;

  // Async texture load (material will be updated when ready)
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTex = tex;
        planeMat.map = tex;
        planeMat.needsUpdate = true;
      })
      .catch(() => {
        // texture failed – keep material untextured
      });
  }

  // -----------------------------------------------------------------
  // 2️⃣  Text content via fontAtlas
  // -----------------------------------------------------------------
  // Resolve text string from possible locations
  let textString = '';
  if (typeof config.textContent === 'string') {
    textString = config.textContent;
  } else if (Array.isArray(config.textContent) && config.textContent[0]?.text) {
    textString = config.textContent[0].text;
  } else if (config.intent?.visualSpec?.textContent?.[0]?.text) {
    textString = config.intent.visualSpec.textContent[0].text;
  }

  if (textString) {
    const textObj = ctx.fontAtlas.createText(textString, {
      fontSize: 31,
      color: (config.visual?.colors?.paper) || '#e8ecf2',
      align: 'left',
    });
    // Slightly in front of the plane to avoid Z‑fighting
    textObj.position.set(0, 0, 0.01);
    root.add(textObj);
  }

  // -----------------------------------------------------------------
  // 3️⃣  Apply scene transform (position / rotation / scale)
  // -----------------------------------------------------------------
  if (Array.isArray(config.position) && config.position.length === 3) {
    root.position.fromArray(config.position);
  }
  if (Array.isArray(config.rotation) && config.rotation.length === 3) {
    root.rotation.fromArray(config.rotation);
  }
  if (Array.isArray(config.scale) && config.scale.length === 3) {
    root.scale.fromArray(config.scale);
  }

  // -----------------------------------------------------------------
  // 4️⃣  Cinematic primitives (none for this spec)
  // -----------------------------------------------------------------
  const primitiveHandlers = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const result = fn(root, prim.params);
        primitiveHandlers.push(result);
      }
    }
  }

  // -----------------------------------------------------------------
  // 5️⃣  Event handlers container (empty per spec)
  // -----------------------------------------------------------------
  root.userData.handlers = {};

  // -----------------------------------------------------------------
  // 6️⃣  Cleanup logic
  // -----------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose primitive resources
    for (const h of primitiveHandlers) {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
      if (h && h.timeline && typeof h.timeline.kill === 'function') {
        h.timeline.kill();
      }
    }

    // Kill any GSAP timelines that might have been created
    gsap.globalTimeline && gsap.globalTimeline.kill();

    // Dispose geometry & material
    planeGeom.dispose();
    planeMat.dispose();

    // Dispose loaded texture
    if (loadedTex && typeof loadedTex.dispose === 'function') {
      loadedTex.dispose();
    }

    // Remove all children
    while (root.children.length) {
      const child = root.children[0];
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
      root.remove(child);
    }
  };

  return root;
}
